#nullable enable
using System;

namespace DwgParser.Core.Format;

public enum HvCondKind { Since, Until, Pre, Versions, Cepsn3 }

public readonly record struct HvCond(HvCondKind Kind, string? A, string? B)
{
    public static HvCond Since(string v) => new(HvCondKind.Since, v, null);
    public static HvCond Until(string v) => new(HvCondKind.Until, v, null);
    public static HvCond Pre(string v) => new(HvCondKind.Pre, v, null);
    public static HvCond Versions(string from, string to) => new(HvCondKind.Versions, from, to);
    public static HvCond Cepsn3() => new(HvCondKind.Cepsn3, null, null);
}

public readonly record struct HvField(string Name, string Type, HvCond[] Conds);

